import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { linkLines } from '../../interfaces/feed-display.interface';

@Injectable({
  providedIn: 'root'
})
export class LinkLineService {

  linkDataSubject = new BehaviorSubject<linkLines[]>([]);
  linkData$ = this.linkDataSubject.asObservable();
  constructor() {

  }

  getLinkLineValues(): BehaviorSubject<linkLines[]> {
    return this.linkDataSubject;
  }

  destroy() {
    this.linkDataSubject.next([]);
  }


}
